<?php

declare(strict_types=1);

namespace App\Shared\Application\Filter;

use App\Shared\Application\ReadModel\BadFilterInput;
use App\Shared\Application\ReadModel\Page;
use App\Shared\Application\ReadModel\Slice;
use App\Shared\Application\ReadModel\Total;

/**
 * The page request, declared next to the filters it arrives with.
 *
 * ADR 004: "a page request is an exposed parameter like any other". So it is part of the
 * declaration, its surface is generated by the same code that generates the filters', and it fails
 * through the same exception. There is no second pipeline, and `page=0` is refused at the same
 * moment `color=mauve` is.
 *
 * Which of the two shapes it produces is fixed when the declaration is written, because the port
 * behind it already decided (rule 8). A `FilterSet` declaring `pages()` can never hand a `Slice` to
 * a read model that wanted one, and vice versa, which is a wiring error caught at the type rather
 * than a runtime surprise.
 *
 * `maxSize` is the one thing option B genuinely takes off a query handler's hands. Under option A
 * the ceiling lives in the handler and every delivery is free to ask for a million; here it is
 * applied at parse time, once, for every delivery at once.
 */
final readonly class Window
{
    public const string PAGE = 'page';
    public const string ITEMS_PER_PAGE = 'itemsPerPage';
    public const string AFTER = 'after';
    public const string SIZE = 'size';
    public const string TOTAL = 'total';

    /**
     * @param Total|null $total the default counting mode, or null when this port does not offer the
     *                          choice and the parameter is therefore not exposed at all
     */
    private function __construct(
        public WindowKind $kind,
        public int $defaultSize,
        public int $maxSize,
        public ?Total $total,
    ) {
    }

    public static function pages(int $defaultSize = 20, int $maxSize = 100, ?Total $total = null): self
    {
        return new self(WindowKind::Pages, $defaultSize, $maxSize, $total);
    }

    /**
     * A keyset window never offers a total, and the signature is where that is stated. Counting a
     * set that moves while you walk it produces a number that was true for nobody.
     */
    public static function slice(int $defaultSize = 20, int $maxSize = 100): self
    {
        return new self(WindowKind::Slice, $defaultSize, $maxSize, null);
    }

    /**
     * @return list<string> the parameter names this window occupies, so a delivery can generate a
     *                      surface for them without knowing which kind it got
     */
    public function parameters(): array
    {
        $names = WindowKind::Pages === $this->kind
            ? [self::PAGE, self::ITEMS_PER_PAGE]
            : [self::AFTER, self::SIZE];

        return null === $this->total ? $names : [...$names, self::TOTAL];
    }

    /**
     * @param array<string, mixed> $raw
     */
    public function parseTotal(array $raw): Total
    {
        if (null === $this->total) {
            return Total::None;
        }

        $raw = $raw[self::TOTAL] ?? null;

        return \is_string($raw) && '' !== $raw ? Total::parse(self::TOTAL, $raw) : $this->total;
    }

    /**
     * @param array<string, mixed> $raw
     */
    public function parse(array $raw): Page|Slice
    {
        if (WindowKind::Pages === $this->kind) {
            return new Page(
                $this->integer(self::PAGE, $raw, 1),
                $this->clamp($this->integer(self::ITEMS_PER_PAGE, $raw, $this->defaultSize)),
            );
        }

        $after = $raw[self::AFTER] ?? null;

        return new Slice(
            \is_string($after) && '' !== $after ? $after : null,
            $this->clamp($this->integer(self::SIZE, $raw, $this->defaultSize)),
        );
    }

    /**
     * Clamped, not refused, and the difference is a product decision rather than a technical one:
     * asking for more than we will give is a reasonable thing for a client to do, while asking for
     * page zero is not a request at all.
     */
    private function clamp(int $size): int
    {
        return min($size, $this->maxSize);
    }

    /**
     * @param array<string, mixed> $raw
     */
    private function integer(string $name, array $raw, int $default): int
    {
        $text = $raw[$name] ?? null;

        if (!\is_string($text) || '' === $text) {
            return $default;
        }

        $value = filter_var($text, \FILTER_VALIDATE_INT);

        if (false === $value) {
            throw BadFilterInput::notAnInteger($name, $text);
        }

        return $value;
    }
}
